/** Exercise real reports generated by the exact-source Vitest suites. Run after the verifier in CI. */
import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, writeFileSync, mkdirSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { spawnSync } from "node:child_process";
const root = process.cwd(), scratch = mkdtempSync(join(tmpdir(),"thl-evidence-"));
const original = ["v2-performance.json","v2-security.json"].map(n=>JSON.parse(readFileSync(join(root,".release-evidence",n),"utf8")));
try {
	mkdirSync(join(scratch,".release-evidence"));
	writeFileSync(join(scratch,"package.json"),readFileSync(join(root,"package.json")));
	const run = (mutate = ()=>{}) => {
		const [p,s] = structuredClone(original); mutate(p,s);
		for (const [n,r] of [["v2-performance.json",p],["v2-security.json",s]])
			writeFileSync(join(scratch,".release-evidence",n),JSON.stringify(r));
		const result = spawnSync(process.execPath,[resolve(root,"scripts/verify-release-evidence.mjs")],{cwd:scratch,encoding:"utf8"});
		assert.ifError(result.error); assert.notEqual(result.status,null);
		return result;
	};
	const baseline=run(); assert.equal(baseline.status,0,baseline.stderr);
	for (const [name, mutate] of Object.entries({
		emptyChecks:p=>{p.workloads[0].checks={}},
		extraCheck:p=>{p.workloads[0].checks.extra="pass"},
		missingCheck:p=>{delete p.workloads[0].checks.validation},
		wrongFixture:p=>{p.workloads[0].fixture.sha256="b".repeat(64)},
		wrongCount:p=>{p.workloads[1].fixture.steps++},
		wrongGeometry:p=>{p.workloads[0].measurements.geometry[0].nodes++},
		invalidGeometryTiming:p=>{p.workloads[0].measurements.geometry[0].layout.maxMs=null},
		unorderedTiming:p=>{p.workloads[0].measurements.geometry[0].projectedGeometry.p95Ms=1e30},
		wrongSamples:p=>{p.workloads[0].measurements.compile.samples=7.5},
		missingHeap:p=>{delete p.workloads[0].measurements.heapDeltaBytes},
		changedBudget:p=>{p.budgets.entities++},
		stalePerformance:p=>{p.source.commit="b".repeat(40)},
		staleSecurity:(p,s)=>{s.source="b".repeat(40)},
		wrongRun:(p,s)=>{s.workflowRun="0"},
		wrongPerformanceAttempt:p=>{p.source.workflowAttempt=String(BigInt(p.source.workflowAttempt)+1n)},
		wrongSecurityAttempt:(p,s)=>{s.workflowAttempt=String(BigInt(s.workflowAttempt)+1n)},
		missingPerformanceAttempt:p=>{delete p.source.workflowAttempt},
		missingSecurityAttempt:(p,s)=>{delete s.workflowAttempt},
		duplicateDepths:(p,s)=>{s.variation.distinctDepths=[2,2,2]},
		missingClass:(p,s)=>{delete s.cases["bad-phase"]},
	})) assert.notEqual(run(mutate).status,0,"accepted malformed evidence: "+name);
	console.info("Release evidence negative regressions passed.");
} finally { rmSync(scratch,{recursive:true,force:true}); }
